typedef struct {
    uint8_t byte1;
    uint8_t byte2;
} DOSBYTES_t;

typedef union {
    uint16_t   palabra;    // 16 bits...
    DOSBYTES_t bytes;      // ...o esos mismos 16 bits como 2 bytes
} U_WORD_BYTE_t;

uint16_t swap(uint16_t ent) {
    U_WORD_BYTE_t uwb;
    uint8_t temp;

    uwb.palabra = ent;
    temp = uwb.bytes.byte1;
    uwb.bytes.byte1 = uwb.bytes.byte2;
    uwb.bytes.byte2 = temp;
    return uwb.palabra;
}

